INSERT INTO public.departments (id, name, overview, url) VALUES (1, 'Accident And Emergency', 'The department of emergency medicine at Labaid Hospital , which work as the quick response team , is staffed hours a day by in- house trauma nurses and vital support services including the blood bank and laboratory services . The emergency department staffs at Labaid always strive to provide patients with the highest quality emergency care and service in an efficient and timely manner.', 'https://labaid.com.bd/en/department/accident-and-emergency');
