INSERT INTO public.departments (id, name, overview, url) VALUES (2, 'Anaesthesiology', 'We make sure that your surgical procedure as safe, comfortable and efficient as possible. An integral support function for all specialties , the department of Anesthesiology and critical care provides inter- disciplinary medical care based on application of Anesthesia in surgery ,Diagnostics , Critical care and Pain management with an optimal evidence based approach.', 'https://labaid.com.bd/en/department/anaesthesiology1');
