INSERT INTO public.departments (id, name, overview, url) VALUES (3, 'Burn & Plastic Surgery', 'Department of Burn, Plastic and Cosmetic Surgery of Labaid Hospitals Dhaka provides exceptional and extensive services to its patients in several aspects of Plastic Surgery. Our post graduate qualified plastic surgeon utilize the latest techniques and provide a wide variety of aesthetic and reconstructive procedures for both men and women with safe, successful outcomes. The department offers both surgical and non-surgical services to help patients look and feel their best.', 'https://labaid.com.bd/en/department/burn-and-plastic');
