INSERT INTO public.departments (id, name, overview, url) VALUES (4, 'Cardiac Surgery', 'Since the commencement of operation of Cardiac Hospital, Cardiac Surgery department has been playing a vital role to serve the cardiac patients. The Department is supported by a well-equipped third generation Critical Care Units and Intensive Care Units. Currently, this department has 2 dedicated operation theatres equipped with modern instruments and machineries which is ready to serve for 24/7. In the middle of 2004, it has started its journey and till now it has performed 10000+ successful surgeries which is indeed an achievement of milestone.
