INSERT INTO public.departments (id, name, overview, url) VALUES (5, 'Cath Lab', 'Labaid hospital provides an inclusive treatment plan for managing various heart conditions including cardiac rehabilitation. Using the best and the latest technology, our skilled Cardiologists, compassionate staff and the well – equipped wards are performing required services.', 'https://labaid.com.bd/en/department/cath-lab-department');
INSERT INTO public.departments (id, name, overview, url) VALUES (6, 'Chemotherapy', 'Labaid offers world-class care at our state-of-the-art facilities for treatment of all types of cancer. Once you and your oncologist or surgeon have decided that chemotherapy may be part of your cancer treatment, they will recommend that you receive a consultation with one of our doctors who will:
INSERT INTO public.departments (id, name, overview, url) VALUES (7, 'Colorectal Surgery', 'Colorectal surgery is a medical operation that is performed on the colon, rectum and anus. Colorectal surgeons, who are also referred to as proctologists, are responsible for carrying out this procedure, which may be necessary to treat a number of conditions.
