INSERT INTO public.departments (id, name, overview, url) VALUES (8, 'Coronary Care Unit - CCU', 'A cardiac care unit (CCU) is a specialized hospital ward designed to treat people with serious or acute heart problems. People who undergo heart surgery also are placed in the CCU as they recover. These wards are equipped to provide specialized treatment for heart conditions and are staffed with medical personnel trained in cardiac care. In many hospitals, CCUs treat a growing number of patients who, in addition to cardiovascular disease, have other chronic health issues that require management. Patients are admitted to the CCU for serious, acute, and/or unstable cardiac conditions that require round-the-clock monitoring and specialized cardiovascular therapy.', 'https://labaid.com.bd/en/department/ccu-department');
INSERT INTO public.departments (id, name, overview, url) VALUES (9, 'Dental', 'Providing comprehensive dental care with expert diagnosis, advanced treatment, and personalized consultation for all dental and oral health needs.', 'https://labaid.com.bd/en/department/dental');
