INSERT INTO public.departments (id, name, overview, url) VALUES (14, 'ENT', 'The ENT Department at Labaid provides diagnosis and treatment of disorders of the head and neck, including particularly the ears, nose, and throat. The department of ENT offers the best care for all ENT related head and neck problems. It also offering the complete range of ENT services under one roof. The Centre is staffed by highly qualified and experienced ENT Surgeon. We adopt an evidence based and multi disciplinary approach to diagnosing and healing patients.
