INSERT INTO public.departments (id, name, overview, url) VALUES (15, 'Fertility Center (IVF)', 'This center aims at being the premier infertility management center in Bangladesh with an array of dedicated services in infertility management and fertility preservation. The center boasts all the specialist services required of during infertility management such as Reproductive medicine specialists, Urologists, Endocrinologist, sophisticated clinical laboratory facilities and latest innovations in minimally invasive gynaecological surgery under one roof. Facilities for fertility preservation by cryopreservation prior to treatment with chemotherapy and surgical interventions do feature our commitment to total services for the patients. All patients of the center are counseled appropriately before, during, between or after treatments.
INSERT INTO public.departments (id, name, overview, url) VALUES (16, 'Gastroenterology', 'Department of Gastroenterology and Hepatology is devoted to the clinical care of patients with gastrointestinal and liver disorders. The department is home to excellent patient care, and our specialists employ the most advanced diagnostic and therapeutic endoscopy services to ensure the best outcomes for each patient. Working closely with a dedicated staff that includes doctors, technologists, nurses, dietitians and more, our care is unsurpassed with the kind of quality and compassion you can expect from a leader in healthcare.
