INSERT INTO public.departments (id, name, overview, url) VALUES (17, 'General And Laparoscopic Surgery', 'The department of general surgery is well equipped with the latest technology and facilities, and is manned by experienced surgeons, nurses and technicians. General Surgery focuses on surgeries of the abdominal organs, breast, thyroid gland and hernias. Operations of the oesophagus , stomach, colon, liver, gallbladder, and bile duct are done with minimally invasive laparoscopic surgery. Procedures such as treatment of varicose veins, circumcision, vasectomies done by our general surgeons.
