INSERT INTO public.departments (id, name, overview, url) VALUES (18, 'Gynaecology & Obstetircs & Laparoscopic Surgery', 'Labaid takes an integrated approach to meet the needs of expectant parents and their newborns. Our childbirth experts are committed to providing exceptional services, including prenatal genetic testing and counseling, childbirth preparation classes, and a variety of wellness amenities. Our Maternal Fetal Medicine team cares for women with high-risk pregnancies.
