INSERT INTO public.departments (id, name, overview, url) VALUES (20, 'Hematology', 'Hematology is the medical specialty that focuses on the treatment of blood disorders and malignancies. Leukemia, lymphoma, and sickle-cell anemia are just a few of the conditions that are treated by hematologists. Hematologist-oncologists are physicians who practice in the field of hematology. Hematologists are also trained in the field of medical oncology (solid tumors), and they may specialize in one or the other, or practice a mix of hematology and oncology.
