INSERT INTO public.departments (id, name, overview, url) VALUES (21, 'Hepatobiliary Surgery', 'Labaid Department of Hepatobiliary Surgery consists of experienced surgeons and anesthetic team who are ready to give outstanding service in Bangladesh. The mission of the department of Hepatobiliary Surgery is to provide best possible service to patients with special emphasis on ethics and quality. We have state of the art surgical instruments ensuring patient’s safety in surgical procedures and providing the best possible service round the clock through our in-house Qualified Specialist Surgeons.', 'https://labaid.com.bd/en/department/liver-pancreatic-and-hepatobiliary-surgery');
