INSERT INTO public.departments (id, name, overview, url) VALUES (22, 'Hepatology', 'Our liver specialists or hepatologists have been at the forefront of groundbreaking advances in the detection and treatment of liver diseases for more than half a century. We have a tradition of excellence and consistently provide compassionate, innovative care.
