INSERT INTO public.departments (id, name, overview, url) VALUES (23, 'ICU', 'The Intensive Care Unit is an expensive resource area and should be reserved for patients with reversible medical conditions with a reasonable prospect of substantial recovery. Patients with the following conditions are candidates for admission to the General Intensive Care Unit.
INSERT INTO public.departments (id, name, overview, url) VALUES (24, 'Interventional Cardiology', 'We believe you deserve nothing less than the very best in cardiovascular care. That is why Labaid has assembled a team of superb cardiologists, cardiac surgeons, and special trained nurse, who are skilled in providing the newest available diagnostics and treatments. Our heart doctors have the expertise to personalize the right treatment plan for you, whether you’re struck with a medical emergency like a heart attack or you’re dealing with an ongoing issue such as arrhythmia.', 'https://labaid.com.bd/en/department/interventional-cardiology');
