INSERT INTO public.departments (id, name, overview, url) VALUES (25, 'Interventional Cardiology & Electro Physiology', 'Patient service with supreme quality has made the Department of Interventional Cardiology and Electro Physiology successful to gain the trustworthiness of the patient. A dedicated team of genius and skilled consultants and junior doctors along with experienced technicians are working dedicatedly for the patient’s health cure which has enabled their professional reputation.
