INSERT INTO public.departments (id, name, overview, url) VALUES (26, 'Laparoscopy', 'Laparoscopy is a wide range of comprehensive and high quality surgical procedures. The department is well equipped with the latest technology and facilities, and is manned by experienced surgeons, nurses and technicians. Operations of the oesophagus, stomach, colon, liver, gallbladder, and bile duct are done with minimally invasive laparoscopic surgery.', 'https://labaid.com.bd/en/department/laparoscopy');
INSERT INTO public.departments (id, name, overview, url) VALUES (27, 'Medicine', 'Our department embodies excellence, inspiration and empowerment in caring for the patients. Staff of the various specialties are world leading experts in their respective fields.
