INSERT INTO public.departments (id, name, overview, url) VALUES (28, 'Medicine & Rheumatology', 'Rheumatology provides advanced diagnosis and treatments for systematic autoimmune diseases, rheumatoid arthritis, lupus, and other musculoskeletal disorders affecting children and adults. Our goal is to provide comprehensive treatment and other therapies to help you to live life to its fullest.
