INSERT INTO public.departments (id, name, overview, url) VALUES (29, 'Nephrology', 'Labaid Hospital equipped with state of the art technical support and is dedicated to providing the best of care and patients suffering from kidney issues. Nephrology is the discipline that deals with the treatment of conditions that affect kidneys . We provide expert diagnosis and treatment of all forms of kidney diseases, such as:
