INSERT INTO public.departments (id, name, overview, url) VALUES (31, 'Neuro Medicine', 'Our highly skilled neurologists and specialized staff work every day to improve the lives of patients with a wide range of neurological disorders. Our Department comprises a network of specialized centers and programs, each providing complete care for a particular condition, including epilepsy, headache, stroke, multiple sclerosis, Parkinson’s disease, brain and spinal tumors, amyotrophic lateral sclerosis (ALS), and neuromuscular disease.
INSERT INTO public.departments (id, name, overview, url) VALUES (32, 'Neurology', 'Diagnosis, prevention and treatment of disorder of nervous system.
