INSERT INTO public.departments (id, name, overview, url) VALUES (33, 'NICU', 'The birth of a child is the happiest moment in any family. But if the child is born unwell or sick then it brings severely bitter experience to a family. Labaid hospital’s Neonatal Intensive Care Unit (NICU) is a very delicate and sensitive part of Labaid hospital where new born babies are treated for life threatening illness. Neonates are cared in a 1:1 basis nursing and are monitored and trained by specialized NICU doctors.
INSERT INTO public.departments (id, name, overview, url) VALUES (34, 'Nuclear Medicine', 'This department uses radioactive material to diagnose different types of disease like cancers, heart diseases, kidney disease, liver and gall bladder disease and certain other abnormalities within the body. Normal X-Rays pass x-rays throughout the patient’s body to get an image whereas Nuclear medicine uses a ‘radiotracer’ which is either injected, swallowed or inhaled which gives out gamma rays which is then picked up by the gamma camera detailing the structure and function of organs and tissues in the patient’s body. The Nuclear Medicine Department of Labaid Hospital offers a number of Nuclear Medicine diagnostic tests using state-of-the-art technology and facilities within the department. The diagnostic service is offered throughout the week and includes:
INSERT INTO public.departments (id, name, overview, url) VALUES (35, 'Oncology', 'Oncology is the field of medical that deals with cancer treatment, from chemotherapy to surgery.
