INSERT INTO public.departments (id, name, overview, url) VALUES (36, 'Ophthalmology', 'The Eye department of Labaid Hospital Dhaka has comprehensive treatment including basic and advanced treatment for patients. Our highly trained doctors offer specialized treatment for a range of eye problems.
