INSERT INTO public.departments (id, name, overview, url) VALUES (37, 'Orthopaedic & Trauma Surgery', 'We offer the best in orthopedic treatment, complex orthopedic surgeries and care for all orthopedic and joint related problems. The department boasts and well trained and highly skilled team of doctors and surgeons. The hospital provides excellent treatment for all sports injuries, joint pains and other common orthopedic conditions.
