INSERT INTO public.departments (id, name, overview, url) VALUES (38, 'Pain Management', 'Now-a-days pain is one of the most common chief complaints by patients which is recorded in the prescription by doctors. This is such a term which may cause at any age due to various reasons like injuries, disorders of nervous system or autoimmune system, arthritis etc. If this pain in the human body continues without any medical treatment, it would create anxieties, depression, lack of concentration on work, muscle spasm etc. in the long run. To release different type of pain like acute, chronic, neuropathic and nociceptive, requirement of medication, injection, therapy and exercise is essential and highly beneficial. As a solution, healthcare providers come up with a comprehensive plan ensuring that patients would have a relaxation from pain as well as solace and thus the pain management plays an indispensable role to feel better and improve the quality of life of our valuable patients.', 'https://labaid.com.bd/en/department/pain-management');
