INSERT INTO public.departments (id, name, overview, url) VALUES (41, 'Pediatric Interventional Cardiology', 'Congenital heart defects of children may cause blood vessels to become narrow. As a solution, using a catheter to insert a very small balloon that inflates to open up the affected blood vessel and improve blood flow is required and these sensitive and complex procedure is done by our professional doctor along with a trained and competent team. Some packages are available which are as follows:', 'https://labaid.com.bd/en/department/pediatric-interventional-cardiology');
