INSERT INTO public.departments (id, name, overview, url) VALUES (42, 'Pediatric Nephrology', 'Pediatric Nephrology is the panoptic care of urinary tracts and kidney diseases of infants or children. It deals with acute and chronic disease related to renal function, blood pressure, fluid and electrolyte disorders in children.', 'https://labaid.com.bd/en/department/pediatric-nephrology');
