INSERT INTO public.departments (id, name, overview, url) VALUES (43, 'Pediatric Neurology', 'Pediatric neurology or child neurology refers to a specialized branch of medicine that deals with the diagnosis and management of neurological conditions in neonates (newborns), infants, children and adolescents. The discipline of child neurology encompasses diseases and disorders of the spinal cord, brain, peripheral nervous system, autonomic nervous system, muscles and blood vessels that affect individuals in these age groups.
