INSERT INTO public.departments (id, name, overview, url) VALUES (44, 'Pediatric Surgery', 'Pediatrics is the branch of medicine dealing with the health and medical care of infants, children, and adolescents from birth up to the age of 18. Pediatric surgery can benefit infants, children and young adult to improve any type of disorder, uncertainty of their health condition. A team of committed consultant and junior doctors are working for this particular surgeries. Neonatal Incentive Care Unit is available to provide the full time care to infants, where dutiful nurses are working 24/7. Some packages/ surgeries are available which are as follows:', 'https://labaid.com.bd/en/department/pediatric-surgery');
