INSERT INTO public.departments (id, name, overview, url) VALUES (45, 'Physical Medicine', 'Physiotherapy or Physical Medicine means treatment and rehabilitation procedures by physical means following diseases, injuries or loss of body parts. The physical means are various exercises, heat, cold, light, sound, electricity, magnetism and massage used to improve circulation, strengthen muscles, encourage return of motions, relief of pain and train or retain an individual to perform the daily activities. Over the years, it has gained vast acceptance as a sophisticated and essential medical technology. Labaid Specialized Hospital''s Physiotherapy Centre employs a multi-disciplinary approach to provide the best possible physiotherapy care for patients across a range of medical conditions.
