INSERT INTO public.departments (id, name, overview, url) VALUES (48, 'Pulmonology And Chest Diseases', 'Respiratory diseases affect every part of the respiratory system, leading to lung disease and breathing problems. Labaid offers comprehensive diagnosis, treatment and continuing care for patients with variety of conditions of the lungs and respiratory tract. Our clinical services are provided by experienced Respiratory Medicine Consultant and backed by state-of-the-art technology.
