INSERT INTO public.departments (id, name, overview, url) VALUES (51, 'Thoracic Surgery', 'Thoracic surgery is the operation which is related to chest. In addition it is used to diagnose or repair lungs affected by cancer, trauma or pulmonary disease. For lung cancer, the surgeon may remove nodules, tumors and lymph nodes to diagnose, stage and treat the disease. Currently, we have some well reputed surgeons who are working devotedly to improve the severe condition of patient health. We have some packages/surgery which are as follows:', 'https://labaid.com.bd/en/department/thoracic-surgery');
