INSERT INTO public.departments (id, name, overview, url) VALUES (54, 'Vaccination Center', 'Vaccines are very important for both adults and children. Vaccines provide immunity against various dangerous diseases like hepatitis-A, hepatitis-B, MMR, HPV, pneumonia, influenza, rotaviral diarrhea, chickenpox, typhoid, meningococcal, cholera, tetanus and rabix etc. In Labaid vaccination center, we are offering various types of vaccines for both children and adults. Labaid vaccination center maintains an excellent cold chain for vaccine storage. All the vaccines are administered by a Medical officer and a vaccine immunization card is provided for each patient. We are offering all the vaccines mentioned below in our vaccination center. All vaccines are subject to dose and age and given accordingly.', 'https://labaid.com.bd/en/department/vaccination-center-2');
INSERT INTO public.departments (id, name, overview, url) VALUES (55, 'Vascular Surgery', 'Labaid Specialized Hospital in its efforts to diversify its services and to introduce new medical technologies sets up The Dept. of Vascular and Endovascular Surgery – one of the new arenas of medical sciences. The LSH vascular centre brings together vascular surgeons and cardiovascular specialists to provide most advanced effective treatment for vascular disorders.
