-- Create ENUM for user roles
DO $$ BEGIN
  CREATE TYPE user_role AS ENUM ('admin', 'doctor', 'patient', 'nurse', 'compounder', 'pharmacist', 'receptionist', 'technician', 'staff');
EXCEPTION
  WHEN duplicate_object THEN null;
END $$;

-- Update existing users table to support roles
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS role user_role DEFAULT 'patient';
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS phone text;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS address text;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS avatar_url text;

-- Drop existing tables
DROP TABLE IF EXISTS public.doctors;
DROP TABLE IF EXISTS public.departments;

-- Create departments table
CREATE TABLE public.departments (
  id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name text NOT NULL,
  overview text,
  url text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Enable RLS for departments
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public read access on departments" ON public.departments FOR SELECT USING (true);

-- Create doctors table
CREATE TABLE public.doctors (
  id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  user_id uuid REFERENCES public.users(id) ON DELETE CASCADE,
  name text NOT NULL,
  designation text,
  speciality text,
  hospital text,
  image_url text,
  profile_url text,
  social_links jsonb,
  dept_id bigint REFERENCES public.departments(id) ON DELETE SET NULL,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Enable RLS for doctors
ALTER TABLE public.doctors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow public read access on doctors" ON public.doctors FOR SELECT USING (true);

